import React, { useState } from "react";

export default function JapTracker() {
  const [days, setDays] = useState(
    Array.from({ length: 30 }, () => ({
      jap: false,
      satsang: false,
      prarthana: false
    }))
  );

  const toggle = (index, field) => {
    const updated = [...days];
    updated[index][field] = !updated[index][field];
    setDays(updated);
  };

  const completedDays = days.filter(
    d => d.jap && d.satsang && d.prarthana
  ).length;

  return (
    <div style={container}>
      <h3>📿 30-Day Jap Tracker (10 min rule)</h3>

      <p>Completed Days: <b>{completedDays}/30</b></p>

      <div style={{ overflowX: "auto" }}>
        <table style={table}>
          <thead>
            <tr>
              <th>Day</th>
              <th>Jap</th>
              <th>Satsang</th>
              <th>Prarthana</th>
            </tr>
          </thead>

          <tbody>
            {days.map((d, i) => (
              <tr key={i}>
                <td>{i + 1}</td>

                <td onClick={() => toggle(i, "jap")} style={cell}>
                  {d.jap ? "✔️" : "⬜"}
                </td>

                <td onClick={() => toggle(i, "satsang")} style={cell}>
                  {d.satsang ? "✔️" : "⬜"}
                </td>

                <td onClick={() => toggle(i, "prarthana")} style={cell}>
                  {d.prarthana ? "✔️" : "⬜"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

const container = {
  background: "#fff",
  padding: "15px",
  borderRadius: "10px",
  marginTop: "20px"
};

const table = {
  width: "100%",
  borderCollapse: "collapse"
};

const cell = {
  cursor: "pointer",
  fontSize: "20px"
};
